mapper.select:
SELECT FROM exam e LEFT JOIN question_bank b ON b.id = e.bank_id AND b.deleted = 0 LEFT JOIN sys_dept d ON d.dept_id = e.dept_id AND d.del_flag = '0'
e.deleted = 0
AND e.exam_name LIKE CONCAT('%', #{examName}, '%')
AND e.status = #{status}
AND e.exam_mode = #{examMode}
ORDER BY e.create_time DESC

