UPDATE exam
exam_name = #{examName}, bank_id = #{bankId}, question_count = #{questionCount}, single_count = #{singleCount}, multi_count = #{multiCount}, judge_count = #{judgeCount}, single_score = #{singleScore}, multi_score = #{multiScore}, judge_score = #{judgeScore}, subject_count = #{subjectCount}, subject_content = #{subjectContent}, subject_attachment = #{subjectAttachment}, position_id = #{positionId}, status = #{status}, duration = #{duration}, pass_line = #{passLine}, published_at = #{publishedAt}, publisher_id = #{publisherId}, update_time = CURRENT_TIMESTAMP
